import{readdir,readFile,mkdir,rename}from'node:fs/promises';import{homedir,tmpdir}from'node:os';import{join}from'node:path';const stamp=Date.now();let moved=0;for(const d of[join(homedir(),'.opencut'),join(tmpdir(),'opencut')]){const paths=[join(d,'mcp-classic-bridge.json'),...(await readdir(join(d,'mcp-classic-bridges')).catch(()=>[])).filter(x=>x.endsWith('.json')).map(x=>join(d,'mcp-classic-bridges',x))];for(const p of paths){let c;try{c=JSON.parse(await readFile(p,'utf8'))}catch{continue}if(!Number.isInteger(c.pid)||c.pid<=0)continue;try{process.kill(c.pid,0);continue}catch(e){if(e.code!=='ESRCH')continue}const dest=join(d,'stale-bridge-backups',String(stamp));await mkdir(dest,{recursive:true});await rename(p,join(dest,(p===join(d,'mcp-classic-bridge.json')?'default-':'')+p.split('/').at(-1)));moved++;}}console.log({moved,backupStamp:stamp});
